
const category=Number(document.body.dataset.category);
let data=[],page=1,view='grid',selection=[];
try{selection=JSON.parse(localStorage.getItem('elvaro-project')||'[]');if(!Array.isArray(selection))selection=[]}catch{}
const grid=document.querySelector('#catalog-grid');
const image=i=>{const xs=[35,258,479,701,922,1144],ws=[212,211,212,210,212,214];return '<div class="product-image" role="img" aria-label="'+['Pendant Light','Chandeliers','Wall Lights','Table Lamps','Outdoor Lights','Track Lights'][i]+'" style="background-image:url(/assets/categories-reference.png);background-size:'+(1402/ws[i]*100)+'% '+(334/199*100)+'%;background-position:'+(xs[i]/(1402-ws[i])*100)+'% '+(69/(334-199)*100)+'%"></div>'};
function filtered(){let list=data.filter(p=>category<0||p.category===category);for(const key of ['application','installation','style']){const values=[...document.querySelectorAll('[data-filter="'+key+'"]:checked')].map(x=>x.value);if(values.length)list=list.filter(p=>values.includes(p[key]))}let sort=document.querySelector('#sort').value;if(sort==='az')list.sort((a,b)=>a.name.localeCompare(b.name));if(sort==='za')list.sort((a,b)=>b.name.localeCompare(a.name));return list}
function render(){const list=filtered(),pages=Math.max(1,Math.ceil(list.length/9));page=Math.min(page,pages);grid.classList.toggle('list-view',view==='list');document.querySelector('#result-count').textContent=list.length+' Design References';grid.innerHTML=list.slice((page-1)*9,page*9).map(p=>'<article class="catalog-card"><a class="catalog-photo" href="/products/details/'+p.id+'.html" data-detail="'+p.id+'">'+image(p.category)+'<span class="sample-tag">REFERENCE</span></a><div><h2>'+p.name+'</h2><p class="meta">'+p.application+' · '+p.style+'<br>Specifications to be confirmed</p><div class="card-actions"><button class="add-project" data-add="'+p.id+'" aria-pressed="'+selection.includes(p.id)+'">'+(selection.includes(p.id)?'Added ✓':'Add to Project')+'</button><button class="detail-link" data-detail="'+p.id+'">View Details →</button></div></div></article>').join('')||'<div class="empty-state">No references match these filters.<br><button class="text-button" onclick="clearFilters()">Clear filters</button></div>';document.querySelector('#pagination').innerHTML=Array.from({length:pages},(_,i)=>'<button data-page="'+(i+1)+'" '+(page===i+1?'aria-current="page"':'')+'>'+(i+1)+'</button>').join('')+(page<pages?'<button data-page="'+(page+1)+'">Next →</button>':'');document.querySelector('#project-count').textContent=selection.length}
function clearFilters(){document.querySelectorAll('[data-filter]').forEach(x=>x.checked=false);page=1;render()}
function details(id){location.href="/products/details/"+id+".html";return;let p=data.find(p=>p.id===id);if(!p)return;document.querySelector('#detailContent').innerHTML='<div class="product-detail-photo">'+image(p.category)+'</div><h2>'+p.name+'</h2><p>'+p.application+' · '+p.installation+' · '+p.style+'</p><p class="note">This is an illustrative design reference, not a confirmed product model. Dimensions, wattage, color temperature, beam angle and IP rating require confirmation with the official catalogue.</p><button data-add="'+p.id+'">'+(selection.includes(p.id)?'REMOVE FROM PROJECT':'ADD TO PROJECT')+'</button>';document.querySelector('#detail').showModal()}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]'),detail=e.target.closest('[data-detail]'),pager=e.target.closest('[data-page]');if(add){let id=add.dataset.add;selection=selection.includes(id)?selection.filter(x=>x!==id):[...selection,id];try{localStorage.setItem('elvaro-project',JSON.stringify(selection))}catch{}render();if(add.closest('#detail'))add.textContent=selection.includes(id)?'REMOVE FROM PROJECT':'ADD TO PROJECT'}if(detail){e.preventDefault();details(detail.dataset.detail)}if(pager){page=+pager.dataset.page;render();document.querySelector('#result-count').scrollIntoView({block:'center'})}document.querySelectorAll('.product-menu[open]').forEach(m=>{if(!m.contains(e.target))m.open=false})});
document.querySelectorAll('[data-filter]').forEach(x=>x.onchange=()=>{page=1;render()});document.querySelector('#sort').onchange=()=>{page=1;render()};document.querySelector('#clear').onclick=clearFilters;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()});
document.querySelector('.mobile-filter-toggle').onclick=e=>{const visible=document.querySelector('.filters').classList.toggle('visible');e.target.setAttribute('aria-expanded',visible)};
document.querySelector('.menu').onclick=()=>document.querySelector('nav').classList.toggle('open');
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.product-menu[open]').forEach(m=>{m.open=false;m.querySelector('summary').focus()})});
function quote(){document.querySelector('#inquiry textarea').value=selection.length?'Selected design references:\n'+selection.map(id=>data.find(p=>p.id===id)?.name||id).join('\n')+'\n\nProject requirements: ':'';document.querySelector('#inquiry').showModal()}
document.querySelector('#form').onsubmit=e=>{e.preventDefault();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([Array.from(new FormData(e.target)).map(([k,v])=>k+': '+v).join('\n')],{type:'text/plain'}));a.download='ELVARO-project-inquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
document.querySelector('#year').textContent=new Date().getFullYear();
fetch('/assets/catalog-data.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{data=d;render()}).catch(()=>grid.innerHTML='<p>Unable to load the catalogue. Please refresh the page.</p>');
